/**
 * Liberation: Captive II (CD32) `GameView`: the city street level, rendered by
 * `tools/liberation/cd32/view-model.ts`, a port of captiveII's own static wall
 * composer (window fill +0x27F8E, visibility pass +0x28646, slot walk +0x2564E,
 * city type handlers +0x27BBA, CPU blitters +0x259F8, backdrop +0x1D794) via
 * `renderCanvas` (192x100, 64 colours).
 * Maps are generated by the game's own PlotGen + CityGen run in a musashi
 * harness at export time (no map files ship); one walker level = one exported
 * (world, zone).
 * Confidence: grid, window, visibility and the composed 6-plane view are
 * byte-exact against the game's code run in the harness (3,300+ poses over 10
 * zones). Palette = AGA base CMAP + wall CMAP as +0x1CA8A loads it.
 * Hypotheses / not done: vector objects (buildings' doors and signs, people,
 * droids, props) are not drawn; only the street layer (z=1) is walkable;
 * stairs/ramps (flags bit 3), drops (bit 4) and door cells (value bit 7) are
 * treated as blocked; the type-6 texture phase is frozen at tick 0.
 */
import type { KeyStateLike, Pose, DrawItem, RGBAColor, PieceBankLookup } from '@seer-project/dungeon';
import type { SlotTableFile } from '@seer-project/dungeon/schema';
import type { GameView } from './games.ts';
import {
  fillWindow, composeView, chunky, canEnter, FWD, VIEW_W, VIEW_H,
  type EngineTables, type Sprite, type CityZone,
} from '../liberation/cd32/view-model.ts';
import { decodeEngine, decodeWall, decodeZone, type EngineJson, type ZoneMeta, type ZoneJson, type WallSpriteJson } from '../liberation/cd32/walker-data.ts';

const STEP_COOLDOWN_MS = 175;
/** The street height layer (CityGen's start position word has z = 1, +0x22B6E). */
export const STREET_Z = 1;

async function fetchJSON<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`GET ${url} -> ${res.status} ${res.statusText}`);
  return res.json() as Promise<T>;
}

export type Op = 'fwd' | 'back' | 'left' | 'right' | 'turnL' | 'turnR';
export interface LibPose { x: number; y: number; facing: number }

/** Pure movement step shared with the tests; null when blocked. Facing 0 N (-y), 1 E, 2 S, 3 W. */
export function stepPose(t: EngineTables, zone: CityZone, pose: LibPose, op: Op, noclip = false): LibPose | null {
  const { x, y, facing } = pose;
  if (op === 'turnL') return { x, y, facing: (facing + 3) & 3 };
  if (op === 'turnR') return { x, y, facing: (facing + 1) & 3 };
  const [fx, fy] = FWD[facing & 3]!;
  const [lx, ly] = FWD[(facing + 3) & 3]!;
  const [dx, dy] = op === 'fwd' ? [fx, fy] : op === 'back' ? [-fx, -fy] : op === 'left' ? [lx, ly] : [-lx, -ly];
  const nx = x + dx, ny = y + dy;
  const inside = nx >= 0 && ny >= 0 && nx < 64 && ny < 64;
  if (noclip ? !inside : !canEnter(t, zone, nx, ny, STREET_Z)) return null;
  return { x: nx, y: ny, facing };
}

export class LiberationView implements GameView {
  readonly id = 'liberation';
  readonly gameLabel = 'Liberation: Captive II';
  readonly items: DrawItem[] = [];
  readonly banks: PieceBankLookup = {};
  readonly slots: SlotTableFile = { schemaVersion: 1, banks: [], slotRows: [] } as unknown as SlotTableFile;
  readonly automap = undefined;
  private pose_: Pose;
  private tick = 0;
  private noclip = false;
  private cooldown = 0;

  private readonly walkerLevel: number;
  private readonly label: string;
  private readonly tables: EngineTables;
  private readonly backdrop: Uint8Array;
  private readonly zone: CityZone;
  private readonly bank0: Sprite[];
  private readonly palette_: RGBAColor[];

  constructor(walkerLevel: number, label: string, tables: EngineTables, backdrop: Uint8Array, zone: CityZone, bank0: Sprite[], palette: RGBAColor[], start: Pose) {
    this.walkerLevel = walkerLevel; this.label = label; this.tables = tables; this.backdrop = backdrop;
    this.zone = zone; this.bank0 = bank0; this.palette_ = palette; this.pose_ = start;
  }
  get levelId(): number { return this.walkerLevel; }
  get levelLabel(): string { return this.label; }
  get pose(): Pose { return this.pose_; }
  get currentTick(): number { return this.tick; }
  get palette(): RGBAColor[] { return this.palette_; }

  update(dtMs: number, keys: KeyStateLike): Pose | null {
    this.tick += dtMs;
    this.cooldown = Math.max(0, this.cooldown - dtMs);
    if (this.cooldown > 0) return null;
    const d = (...c: string[]) => c.some((k) => keys.isDown(k));
    const op: Op | null = d('KeyQ', 'ArrowLeft') ? 'turnL' : d('KeyE', 'ArrowRight') ? 'turnR'
      : d('KeyW', 'ArrowUp') ? 'fwd' : d('KeyS', 'ArrowDown') ? 'back' : d('KeyA') ? 'left' : d('KeyD') ? 'right' : null;
    if (!op) return null;
    const next = stepPose(this.tables, this.zone, { x: this.pose_.x, y: this.pose_.y, facing: this.pose_.facing }, op, this.noclip);
    if (!next) return null;
    this.cooldown = STEP_COOLDOWN_MS;
    this.pose_ = { level: this.walkerLevel, x: next.x, y: next.y, facing: next.facing as Pose['facing'] };
    return this.pose_;
  }
  setPose(pose: Pose): void { this.pose_ = pose; }
  setNoclip(on: boolean): void { this.noclip = on; }
  interactCodes(): string[] { return []; }
  automapCodes(): string[] { return []; }
  pick(): void { /* no hotspots */ }

  /** 192x100 colour indices for the current pose (exposed for tests). */
  frame(): Uint8Array {
    const win = fillWindow(this.tables, this.zone, this.pose_.x, this.pose_.y, STREET_Z, this.pose_.facing);
    return chunky(composeView(this.tables, this.bank0, win, 0, this.backdrop));
  }

  renderCanvas(ctx: CanvasRenderingContext2D): void {
    const px = this.frame();
    const img = ctx.createImageData(VIEW_W, VIEW_H);
    for (let i = 0; i < px.length; i++) {
      const c = this.palette_[px[i]!] ?? { r: 255, g: 0, b: 255, a: 255 };
      img.data[i * 4] = c.r; img.data[i * 4 + 1] = c.g; img.data[i * 4 + 2] = c.b; img.data[i * 4 + 3] = 255;
    }
    ctx.canvas.width = VIEW_W;
    ctx.canvas.height = VIEW_H;
    ctx.putImageData(img, 0, 0);
  }
}

export async function liberationLevelList(assetBase: string): Promise<Array<{ id: number; label: string }>> {
  const zones = await fetchJSON<ZoneMeta[]>(`${assetBase}/walker/zones.json`);
  return zones.map(({ id, label }) => ({ id, label }));
}

export async function loadLiberationView(assetBase: string, levelId: number, startPose: Pose | null): Promise<LiberationView> {
  const w = `${assetBase}/walker`;
  const [engine, zones] = await Promise.all([fetchJSON<EngineJson>(`${w}/engine.json`), fetchJSON<ZoneMeta[]>(`${w}/zones.json`)]);
  const meta = zones.find((z) => z.id === levelId) ?? zones.find((z) => z.world === 0 && z.zone === 8) ?? zones[0]!;
  const [zj, wall] = await Promise.all([
    fetchJSON<ZoneJson>(`${w}/zone-w${meta.world}z${meta.zone}.json`),
    fetchJSON<WallSpriteJson[]>(`${w}/walls/${String(meta.wall).padStart(2, '0')}.json`),
  ]);
  const { tables, backdrop } = decodeEngine(engine);
  const palette = zj.palette.map(([r, g, b]) => ({ r, g, b, a: 255 }));
  const start: Pose = startPose && startPose.level === meta.id ? startPose
    : { level: meta.id, x: meta.start.x, y: meta.start.y, facing: (meta.start.facing & 3) as Pose['facing'] };
  return new LiberationView(meta.id, meta.label, tables, backdrop, decodeZone(meta, zj), decodeWall(wall), palette, start);
}
